draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // older dog
  ctx.lineWidth = 3;
  ctx.strokeStyle = 'black';
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2 - 100, H/2, 30, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H/2 + 30);
  ctx.lineTo(W/2 - 100, H/2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H/2 + 50);
  ctx.lineTo(W/2 - 80, H/2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H/2 + 50);
  ctx.lineTo(W/2 - 120, H/2 + 70);
  ctx.stroke();

  // puppy
  ctx.beginPath();
  ctx.arc(W/2 + 100, H/2, 20 + 10 * Math.sin(t), 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 100, H/2 + 20 + 10 * Math.sin(t));
  ctx.lineTo(W/2 + 100, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 100, H/2 + 35);
  ctx.lineTo(W/2 + 80, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 100, H/2 + 35);
  ctx.lineTo(W/2 + 120, H/2 + 50);
  ctx.stroke();

  // teaching
  ctx.beginPath();
  ctx.moveTo(W/2 - 90, H/2 + 60);
  ctx.lineTo(W/2 + 90, H/2 + 40 + 10 * Math.sin(t));
  ctx.stroke();

  ctx.restore();
}
